import { StyleFn } from "..";

export const Drawer: StyleFn = (theme, mode) => {
  const { color, elevation } = theme;

  return {
    root: {
      position: "fixed",
      zIndex: elevation.zindex.drawer,
      boxShadow: elevation.level3,
      display: "flex",
      flexDirection: "column",
      overflowY: "auto",
      height: "100vh",
      outline: 0,
      backgroundColor: color.surface.elevation[4][mode],
      color: color.text.neutral.strong[mode],
    },
    modal: {
      zIndex: elevation.zindex.drawer,
    },
    _horizontal: {
      width: "100%",
      maxWidth: "100vw",
      height: "auto",
    },
    _top: {
      top: 0,
      left: 0,
    },
    _bottom: {
      bottom: 0,
      left: 0,
    },
    _left: {
      top: 0,
      left: 0,
    },
    _right: {
      top: 0,
      right: 0,
    },
    _dark: {
      backgroundColor: color.surface.elevation[4].dark,
      color: color.text.neutral.strong.dark,
    },
    _light: {
      backgroundColor: color.surface.elevation[4].light,
      color: color.text.neutral.strong.light,
    },
  };
};
